flags.typeql:
match
  $p isa person;
  $m isa movie;
  (producer: $p, film: $m) isa produced;
  $p has born $bornp;
  $bornp > 1960;
  $m has title $titlem;
  $m has votes $votesm;
  $m has tagline $taglinem;
  $m has released $releasedm;
limit 5;
fetch {
  "title": $titlem,
  "votes": $votesm,
  "tagline": $taglinem,
  "released": $releasedm
};

match
  $m isa movie, has tagline "Speed has no limits";
  $p isa person;
  (actor: $p, film: $m) isa acted_in;
  $p has name $namep;
limit 3;
fetch {
  "name": $namep
};

match
  $m isa movie, has tagline "Speed has no limits";
  $p isa person;
  (producer: $p, film: $m) isa produced;
  $m has title $titlem;
  $p has name $namep;
fetch {
  "movie": $titlem,
  "producer": $namep
};

match
  (actor: $p, film: $m) isa acted_in;
  $p has name $n;
  $m has title $t;
limit 3;
fetch {
  "actor": $n,
  "movie": $t
};

match
  $m isa movie;
  not { (reviewer: $r, film: $m) isa reviewed; };
  $m has title $titlem;
limit 5;
fetch {
  "title": $titlem
};

match
  $m isa movie, has title $t;
  (actor: $p1, film: $m) isa acted_in;
  (actor: $p2, film: $m) isa acted_in;
  (actor: $p3, film: $m) isa acted_in;
  (actor: $p4, film: $m) isa acted_in;
  not { $p1 is $p2; };
  not { $p1 is $p3; };
  not { $p1 is $p4; };
  not { $p2 is $p3; };
  not { $p2 is $p4; };
  not { $p3 is $p4; };
fetch {
  "title": $t
};

match
  $p isa person;
  $laurence isa person, has name "Laurence Fishburne";
  follows (follower: $p, followed: $laurence);
  follows (follower: $laurence, followed: $p);
  $p has name $name;
limit 5;
fetch {
  "name": $name
};

with fun max_votes() -> integer:
  match $m isa movie, has votes $v;
  return max($v);
match
  $m isa movie, has votes $v, has title $title;
  let $max = max_votes();
  $v == $max;
  acted_in (actor: $p, film: $m);
  $p has name $name;
fetch {
  "movie": $title,
  "actor": $name
};

match
  $m isa movie;
  $m has released $released;
  $released >= 2005;
  $released <= 2010;
  $m has tagline "Speed has no limits";
fetch {
  "title": $m.title
};

match
  $p isa person, has name $n;
  $rev isa reviewed (reviewer: $p, film: $m), has summary "Silly, but fun";
reduce $silly_reviews = count($rev) groupby $n;
sort $silly_reviews desc;
limit 1;
fetch {
  "name": $n,
  "silly_reviews": $silly_reviews
};

match
  $p isa person, has name $n;
  $ai isa acted_in (actor: $p, film: $m), has roles $r;
reduce $total_roles = count($r) groupby $p, $n;
sort $total_roles desc;
limit 3;
fetch {
  "name": $n,
  "total_roles": $total_roles
};

match
  $p isa person;
  $m isa movie;
  (director: $p, film: $m) isa directed;
  (producer: $p, film: $m) isa produced;
  (actor: $p, film: $m) isa acted_in;
  $p has name $namep;
  $m has title $titlem;
limit 3;
fetch {
  "person": $namep,
  "movie": $titlem
};

match
  $p1 isa person;
  $p2 isa person;
  follows (follower: $p1, followed: $p2);
  follows (follower: $p2, followed: $p1);
  $p1 has name $namep1;
  $p2 has name $namep2;
  $namep1 < $namep2;
limit 3;
fetch {
  "person1": $namep1,
  "person2": $namep2
};
